// Re-total and re-rank sites for new weights, in the browser.
// This is a port of backend/api/scoring.py (normalise_weights, total_score, assign_ranks, retotal).
// It must give exactly the same totals and ranks as the API: frontend/tests/fixtures/retotal_cases.json is
// generated by Python from the backend and checked by tests/weights.test.mjs. Keep both in step.
// Pure functions, no DOM: a redesigned interface can reuse this file unchanged.

export const KEYS = ["cooling", "connectivity", "shade"];

/** Weights scaled to sum to 1 (same order of operations as Python's sum(), so floats match). */
export function normaliseWeights(weights) {
  const total = KEYS.reduce((sum, k) => sum + weights[k], 0);
  if (!(total > 0)) throw new Error("weights must sum to more than 0");
  return Object.fromEntries(KEYS.map((k) => [k, weights[k] / total]));
}

/**
 * Round to one decimal place exactly as Python's round(x, 1): the exact binary value is rounded, and an exact
 * tie goes to the even digit (72.25 -> 72.2). Math.round and toFixed(1) round ties up and would disagree.
 */
export function round1(x) {
  if (!Number.isFinite(x)) return x;
  const negative = x < 0 || Object.is(x, -0);
  const exact = Math.abs(x).toFixed(60); // toFixed gives the exact decimal expansion of the double
  const dot = exact.indexOf(".");
  const frac = exact.slice(dot + 1);
  let tenths = BigInt(exact.slice(0, dot) + frac[0]); // whole number of tenths, truncated
  const deciding = frac[1];
  const beyond = frac.slice(2);
  let up = false;
  if (deciding > "5") up = true;
  else if (deciding === "5") up = /[1-9]/.test(beyond) ? true : tenths % 2n === 1n; // exact tie: round half to even
  if (up) tenths += 1n;
  const out = Number(tenths) / 10;
  return negative ? -out : out;
}

/** Weighted total of the three 0-100 scores, rounded to 1 decimal. */
export function totalScore(cooling, connectivity, shade, weights) {
  const w = normaliseWeights(weights);
  return round1(cooling * w.cooling + connectivity * w.connectivity + shade * w.shade);
}

/** Rank 1 = highest score_total; ties broken by site_id so the order is stable. Returns new feature objects. */
export function assignRanks(features) {
  const order = [...features].sort((a, b) => {
    const pa = a.properties, pb = b.properties;
    if (pa.score_total !== pb.score_total) return pb.score_total - pa.score_total;
    return pa.site_id < pb.site_id ? -1 : pa.site_id > pb.site_id ? 1 : 0;
  });
  return order.map((f, i) => ({ ...f, properties: { ...f.properties, rank: i + 1 } }));
}

/** New features with score_total and rank recomputed for `weights`, sorted by rank. Inputs are not modified. */
export function retotal(features, weights) {
  const updated = features.map((f) => {
    const p = f.properties;
    for (const k of ["score_cooling", "score_connectivity", "score_shade"]) {
      if (!Number.isFinite(p[k])) throw new Error(`site ${p.site_id} has no ${k}`);
    }
    const total = totalScore(p.score_cooling, p.score_connectivity, p.score_shade, weights);
    return { ...f, properties: { ...p, score_total: total } };
  });
  return assignRanks(updated);
}

/** Each weight as a whole-number share of the total (for slider labels). Sums to 100 where possible. */
export function sharePercent(weights) {
  const w = normaliseWeights(weights);
  return Object.fromEntries(KEYS.map((k) => [k, Math.round(w[k] * 100)]));
}

/**
 * How much the top of the ranking changed: how many of the top `n` sites in `after` were not in the top `n` of `before`.
 * Both lists are features with a rank. Used for the note after a slider move ("3 of the top 10 changed").
 */
export function topChange(before, after, n = 10) {
  const topIds = (features) => new Set(
    [...features].sort((a, b) => a.properties.rank - b.properties.rank).slice(0, n).map((f) => f.properties.site_id));
  const was = topIds(before);
  const now = [...topIds(after)];
  return { changed: now.filter((id) => !was.has(id)).length, n: Math.min(n, now.length) };
}
